  const currentLabel = String(content.currentLabel ?? title);
  const siteMode     = String(content.siteMode     ?? "multipage");

  const GOLD  = "#CFA968";
  const DARK  = "#1c1c1c";
  const WHITE = "#ffffff";
  const MUTED = "rgba(255,255,255,0.55)";
